<?php
require_once __DIR__ . '/../lib/bootstrap.php';
require_role('student');
$aid = get_int('id');
$s = db()->prepare('SELECT a.*,e.title exam_title,e.total_score,e.instructions,s.title subject_title FROM attempts a JOIN exams e ON e.id=a.exam_id JOIN subjects s ON s.id=e.subject_id WHERE a.id=? AND a.student_id=?');
$s->execute([$aid,current_user()['id']]);
$attempt = $s->fetch();
if (!$attempt) exit('کارنامه پیدا نشد.');
$s = db()->prepare('SELECT q.question_text,q.chapter,q.score,q.question_type,a.answer_text,a.is_correct,a.awarded_score,a.teacher_comment,o.option_text selected_text FROM answers a JOIN questions q ON q.id=a.question_id LEFT JOIN question_options o ON o.id=a.selected_option_id WHERE a.attempt_id=? ORDER BY q.sort_order');
$s->execute([$aid]);
$answers = $s->fetchAll();
$correct = 0; $answered = 0; $pendingReview = 0; $chapterStats = [];
$typeStats = ['mcq'=>['total'=>0,'earned'=>0,'max'=>0],'true_false'=>['total'=>0,'earned'=>0,'max'=>0],'short'=>['total'=>0,'earned'=>0,'max'=>0]];
foreach ($answers as $answer) {
    if ($answer['answer_text'] !== null || $answer['selected_text'] !== null) $answered++;
    if ((int)$answer['is_correct'] === 1) $correct++;
    if ($answer['is_correct'] === null) $pendingReview++;
    $chapter = trim((string)($answer['chapter'] ?? ''));
    if ($chapter !== '') { if (!isset($chapterStats[$chapter])) $chapterStats[$chapter] = ['count'=>0,'earned'=>0,'max'=>0]; $chapterStats[$chapter]['count']++; $chapterStats[$chapter]['earned'] += (float)($answer['awarded_score'] ?? 0); $chapterStats[$chapter]['max'] += (float)$answer['score']; }
    $type = $answer['question_type'];
    if (isset($typeStats[$type])) { $typeStats[$type]['total']++; $typeStats[$type]['earned'] += (float)($answer['awarded_score'] ?? 0); $typeStats[$type]['max'] += (float)$answer['score']; }
}
$percentage = (float)($attempt['percentage'] ?? 0);
$feedback = $percentage >= 90 ? 'عملکرد بسیار عالی است؛ همین روند را ادامه دهید.' : ($percentage >= 70 ? 'عملکرد خوب است؛ با مرور پاسخ‌های نادرست می‌توانید نتیجه را بهتر کنید.' : ($percentage >= 50 ? 'نیاز به تمرین بیشتر در مباحث آزمون دارید؛ سؤال‌های نادرست را مرور کنید.' : 'پیشنهاد می‌شود مباحث پایه را دوباره مطالعه کنید و با تمرین‌های کوتاه شروع نمایید.'));
$title = 'کارنامه آزمون';
require __DIR__ . '/../partials/header.php';
?>
<div class="result-hero card"><div><span class="eyebrow">کارنامهٔ آزمون</span><h1><?= e($attempt['exam_title']) ?></h1><p class="muted"><?= e($attempt['subject_title']) ?> — تلاش شمارهٔ <?= e((string)($attempt['attempt_no'] ?? 1)) ?></p></div><div class="result-score-ring"><strong><?= format_score($percentage) ?>%</strong><span>درصد نهایی</span></div></div>
<div class="grid grid-4 result-summary-grid"><div class="card stat"><span>نمره</span><strong><?= format_score($attempt['score']) ?> / <?= format_score($attempt['total_score']) ?></strong></div><div class="card stat"><span>پاسخ صحیح</span><strong><?= number_format($correct) ?> از <?= number_format(count($answers)) ?></strong></div><div class="card stat"><span>پاسخ‌داده‌شده</span><strong><?= number_format($answered) ?> از <?= number_format(count($answers)) ?></strong></div><div class="card stat"><span>وضعیت تشریحی</span><strong><?= $pendingReview ? number_format($pendingReview).' مورد' : 'بررسی شد' ?></strong></div></div>
<div class="card result-progress-card"><div class="section-heading"><div><span class="eyebrow">خلاصهٔ عملکرد</span><h2>وضعیت کلی شما</h2></div><span class="badge <?= $percentage >= 70 ? 'success' : 'warning' ?>"><?= e($percentage >= 80 ? 'قوی' : ($percentage >= 50 ? 'نیازمند مرور' : 'نیازمند تمرین')) ?></span></div><div class="progress result-progress"><span style="width:<?= min(100,max(0,$percentage)) ?>%"></span></div><div class="result-progress-labels"><span>۰٪</span><strong><?= format_score($percentage) ?>٪</strong><span>۱۰۰٪</span></div><div class="alert info"><strong>بازخورد خودکار:</strong> <?= e($feedback) ?></div><?php if ($pendingReview): ?><div class="alert warning"><?= number_format($pendingReview) ?> پاسخ تشریحی هنوز نیازمند بررسی معلم است؛ نمرهٔ نهایی ممکن است تغییر کند.</div><?php endif; ?><div class="grid grid-3 result-type-grid"><?php foreach (['mcq'=>'تستی','true_false'=>'صحیح/غلط','short'=>'پاسخ کوتاه'] as $type=>$label): $st=$typeStats[$type]; $rate=$st['max']>0?$st['earned']/$st['max']*100:0; ?><div class="result-type-card"><strong><?= format_score($rate) ?>%</strong><span><?= e($label) ?></span><small><?= number_format($st['total']) ?> سؤال</small></div><?php endforeach; ?></div></div>
<?php if ($chapterStats): ?><div class="card"><div class="section-heading"><div><span class="eyebrow">تحلیل آموزشی</span><h2>عملکرد بر اساس فصل و مبحث</h2></div></div><div class="table-wrap"><table class="table"><thead><tr><th>فصل یا مبحث</th><th>تعداد سؤال</th><th>نمره کسب‌شده</th><th>درصد عملکرد</th><th>وضعیت</th></tr></thead><tbody><?php foreach ($chapterStats as $chapter=>$st): $rate=$st['max']>0?$st['earned']/$st['max']*100:0; ?><tr><td><?= e($chapter) ?></td><td><?= e((string)$st['count']) ?></td><td><?= format_score($st['earned']) ?> از <?= format_score($st['max']) ?></td><td><?= format_score($rate) ?>%</td><td><?= e($rate>=80?'قوی':($rate>=50?'نیازمند مرور':'نیازمند تمرین بیشتر')) ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?>
<div class="card"><div class="section-heading"><div><span class="eyebrow">مرور آزمون</span><h2>جزئیات پاسخ‌ها</h2></div><span class="muted"><?= number_format(count($answers)) ?> سؤال</span></div><?php foreach ($answers as $i=>$answer): $answerStatus = $answer['is_correct'] === null ? 'pending' : ((int)$answer['is_correct'] ? 'correct' : 'wrong'); ?><article class="result-answer question <?= e($answerStatus) ?>"><div class="result-answer-head"><strong><?= ($i+1).'. '.e($answer['question_text']) ?></strong><span class="badge <?= $answerStatus==='correct'?'success':($answerStatus==='pending'?'warning':'') ?>"><?= $answerStatus==='correct'?'صحیح':($answerStatus==='pending'?'در انتظار بررسی':'نادرست') ?></span></div><?php if (!empty($answer['chapter'])): ?><p class="muted">فصل / مبحث: <?= e($answer['chapter']) ?></p><?php endif; ?><p><strong>پاسخ شما:</strong> <?= e($answer['selected_text'] ?? $answer['answer_text'] ?? 'بدون پاسخ') ?></p><p>نمره کسب‌شده: <?= format_score($answer['awarded_score'] ?? 0) ?> از <?= format_score($answer['score']) ?></p><?php if ($answer['teacher_comment']): ?><div class="result-teacher-comment"><strong>بازخورد معلم:</strong><br><?= nl2br(e($answer['teacher_comment'])) ?></div><?php endif; ?></article><?php endforeach; ?></div>
<div class="actions result-actions"><a class="btn btn-light" href="<?= e(url('student/feedback.php')) ?>">بازخوردهای آموزشی من</a><a class="btn btn-light" href="<?= e(url('reports/share.php?id='.$aid)) ?>">ساخت لینک اشتراک</a><a class="btn btn-success" href="<?= e(url('reports/student_export.php?id='.$aid)) ?>">خروجی Excel</a><button class="btn btn-primary" onclick="window.print()">چاپ کارنامه</button></div>
<?php require __DIR__ . '/../partials/footer.php'; ?>
